// PoC: verify.ts skips the timestamp check when the header has no t= field.
// Logic is copied from src/webhooks/verify.ts; run with: node missing_t_bypass.js
const crypto = require("crypto");
const TOLERANCE_SECONDS = 300;

function verifyWebhook(rawBody, header, secret) {
  const parts = Object.fromEntries(header.split(",").map(p => p.split("=")));
  const t = parts["t"];
  const sig = parts["v1"];
  if (!sig) return false;
  if (t) {
    const age = Math.abs(Math.floor(Date.now() / 1000) - Number(t));
    if (age > TOLERANCE_SECONDS) return false;
  }
  const expected = crypto.createHmac("sha256", secret)
    .update(`${t ?? ""}.`).update(rawBody).digest("hex");
  return expected === sig;
}

const secret = "whsec_test";
